import{_ as a,C as r,o as i,c,j as t,a as d,E as n,a2 as s}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Knowledge","description":"","frontmatter":{"title":"Knowledge"},"headers":[],"relativePath":"en/guide/knowledge.md","filePath":"en/guide/knowledge.md"}'),l={name:"en/guide/knowledge.md"};function h(g,e,u,p,m,w){const o=r("Capture");return i(),c("div",null,[e[0]||(e[0]=t("h1",{id:"knowledge",tabindex:"-1"},[d("Knowledge "),t("a",{class:"header-anchor",href:"#knowledge","aria-label":'Permalink to "Knowledge"'},"​")],-1)),e[1]||(e[1]=t("p",null,"This screen gathers everything that has been decided and written for the project: decisions (ADR), open questions (BQO) and framing documents. You come here to find out why a choice was made, or to record a decision.",-1)),n(o,{name:"connaissance",alt:"The Knowledge screen: scope tree on the left, decision DEC-01 on the right"}),e[2]||(e[2]=s('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>Scope</strong> (left column): the Project, epics and stories tree, with a <strong>Search…</strong> field and a <strong>Status</strong> filter (<strong>All</strong> / <strong>Hide done</strong>). Click a node to limit the screen to that scope. You can resize the column with the mouse.</li><li><strong>Breadcrumb</strong> (top right): <code>Project › Epic … › Story …</code>, the scope being shown.</li><li><strong>Search within the lens…</strong>: filters the displayed content. The <code>/</code> or <code>Cmd/Ctrl+F</code> shortcut puts the cursor in this field.</li><li><strong>The lenses</strong> (tabs): one per type of content, with its counter — <strong>Decisions (ADR)</strong>, <strong>Questions (BQO)</strong>, and those that read the framing documents: Project framing (at Project level), Glossary, Analysis, Architecture, Specs, API contract, Plan and Acceptance (from an epic down). Only lenses with content in the scope are shown; on a story, <strong>Decisions (ADR)</strong> and <strong>Questions (BQO)</strong> always stay visible, even empty, so that you can add to them.</li><li><strong>The content</strong>: for example a decision card with its identifier (<code>DEC-01</code>), status (<strong>Accepted</strong>), date, title, text and consequences.</li><li>On the <strong>Project framing</strong> lens, at Project level, a banner shows the <strong>Next layer</strong> to write, or &quot;Project framing complete — all 4 layers are written.&quot;</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Change scope</strong>: click a project, epic or story in <strong>Scope</strong>. On opening, the screen goes back to the last scope and lens you viewed in this project; the first time, it lands on the active story.</li><li><strong>Search</strong>: type in <strong>Search…</strong> (tree) or <strong>Search within the lens…</strong> (content). Matching terms are highlighted.</li><li><strong>Add a decision</strong>: on a story, in the Decisions (ADR) lens, click <strong>+ Add a decision</strong> and fill in the form (title, context, decision, consequences, rejected alternatives).</li><li><strong>Add or resolve a question</strong>: on a story, in the Questions (BQO) lens, <strong>+ Add a question</strong> and fill in <strong>Question</strong>, <strong>Impact</strong> and <strong>Suggestion</strong>. On an open question of a story, <strong>Resolve</strong>, type the <strong>Answer</strong>, then <strong>Confirm</strong>. At Project or Epic level, questions can be read but not resolved: go down to their story.</li><li><strong>Complete the framing documents</strong>: on a story, this button creates the missing OPALE documents. The screen tells you how many were created, or that framing is already complete.</li></ul><p>On a story, even a new and empty one, these buttons are always there: <strong>Complete the framing documents</strong> on every lens, <strong>+ Add a decision</strong> and <strong>+ Add a question</strong> on their own lens.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Filter facets (status, impact, origin) appear depending on the lens and the scope.</li><li>A lens with no content in the scope is not shown. If none is left, the screen shows &quot;No knowledge available in this scope.&quot;: pick another item in the tree.</li></ul><h3 id="view-a-task" tabindex="-1">View a task <a class="header-anchor" href="#view-a-task" aria-label="Permalink to &quot;View a task&quot;">​</a></h3><p>Clicking a task in the tree shows its <strong>card</strong> at the top: what needs to be done, what it produced, and its commits. A task carries no decision or question of its own: what follows the card is its story&#39;s knowledge, and the page says so.</p>',9)),n(o,{name:"connaissance-tache",alt:"Knowledge with a task selected: its card, then its story's knowledge"}),e[3]||(e[3]=s('<h2 id="with-an-ai-agent" tabindex="-1">With an AI agent <a class="header-anchor" href="#with-an-ai-agent" aria-label="Permalink to &quot;With an AI agent&quot;">​</a></h2><p>Agents record the same material with <code>effortless_decision_add</code>, <code>effortless_question_ask</code> and <code>effortless_question_resolve</code>, read it with <code>effortless_project_tree</code> and <code>effortless_story_items</code>, and search it with <code>effortless_docs_search</code>. The <strong>Complete the framing documents</strong> button matches <code>effortless_cadrage_docs_scaffold</code>.</p>',2))])}const _=a(l,[["render",h]]);export{y as __pageData,_ as default};
